schema_ddl:
CREATE TABLE registrazioni (
    id SERIAL PRIMARY KEY,
    data_registrazione DATE NOT NULL,
    importo NUMERIC(12,2) NOT NULL CHECK (importo != 0),
    tipo_voce TEXT NOT NULL,
    fornitore TEXT,
    totale_per_fornitore NUMERIC(12,2) GENERATED ALWAYS AS (
        CASE WHEN fornitore IS NOT NULL THEN importo ELSE NULL END
    ) STORED,
    totale_per_tipo NUMERIC(12,2) GENERATED ALWAYS AS (
        CASE WHEN tipo_voce IS NOT NULL THEN importo ELSE NULL END
    ) STORED,
    totale_generale NUMERIC(12,2) GENERATED ALWAYS AS (importo) STORED
);

CREATE TABLE categorie_contabili (
    id SERIAL PRIMARY KEY,
    nome_categoria TEXT NOT NULL UNIQUE,
    descrizione TEXT
);

CREATE TABLE fornitori (
    id SERIAL PRIMARY KEY,
    nome_fornitore TEXT NOT NULL UNIQUE,
    partiva_iva TEXT CHECK (partiva_iva ~ '^[A-Z]{2}[0-9]{11}$|^$'),
    data_inserimento TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE riepiloghi (
    id SERIAL PRIMARY KEY,
    periodo DATE NOT NULL,
    somma_totale NUMERIC(12,2) NOT NULL DEFAULT 0,
    conteggio_registrazioni INT NOT NULL DEFAULT 0,
    CHECK (somma_totale >= 0 AND conteggio_registrazioni >= 0)
);
